package odc;

import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.world.World;
import net.minecraft.util.math.BlockPos;
import static odc.EventJournal.*;

/** Forge integration. Scope is a stable device ID, not an owner-wide wallet or transient numeric ID. */
final class EventSystem {
    static UUID scope(Tiles.Owned t){return t instanceof Tiles.Rack?((Tiles.Rack)t).id:t instanceof Tiles.Computer?((Tiles.Computer)t).id:null;}
    static Set<UUID> scopes(Tiles.Owned t){Set<UUID> ids=new HashSet<>();Network.Domain domain=Network.scan(t.getWorld(),t.getPos());if(domain!=null)for(Tiles.Owned device:domain.devices)if(Objects.equals(t.owner,device.owner)&&scope(device)!=null)ids.add(scope(device));if(scope(t)!=null)ids.add(scope(t));return ids;}
    static void rack(Tiles.Rack r,int bay,Level l,Category c,String code,String message){if(r.getWorld()==null||r.getWorld().isRemote||r.owner==null)return;UUID id=r.isServer(bay)?ClusterScheduler.serverId(r.slots.get(bay)):r.id;TaskData d=TaskData.get(r.getWorld());d.record(r.owner,r.id,id,l,c,r.isServer(bay)?Target.SERVER:Target.RACK,code,message,-1,0);}
    static void moveRackHistory(Tiles.Rack r,UUID destination){if(r.owner!=null){TaskData d=TaskData.get(r.getWorld());d.journal.move(r.owner,r.id,destination);d.markDirty();}}
    static void terminalPower(Tiles.Computer c,boolean on){if(c.owner!=null)TaskData.get(c.getWorld()).record(c.owner,c.id,c.id,on?Level.INFO:Level.WARNING,Category.POWER,Target.NONE,on?"terminal_power_restored":"terminal_power_lost",on?"Terminal powered on":"Terminal power lost",-1,0);}
    static void terminalOpened(Tiles.Computer c){if(c.getWorld()!=null&&!c.getWorld().isRemote&&c.owner!=null)TaskData.get(c.getWorld()).record(c.owner,c.id,c.id,Level.INFO,Category.SYSTEM,Target.NONE,"terminal_opened","DataOS terminal opened",-1,0);}
    static UUID survivor(Tiles.Owned device){Set<UUID> ids=scopes(device);ids.remove(scope(device));return ids.stream().min(Comparator.comparing(UUID::toString)).orElse(null);}
    static NBTTagCompound tag(Entry e){NBTTagCompound n=new NBTTagCompound();n.setUniqueId("Key",e.id);n.setUniqueId("Owner",e.owner);n.setUniqueId("Scope",e.scope);n.setUniqueId("Origin",e.origin);if(e.source!=null)n.setUniqueId("Source",e.source);n.setLong("First",e.first);n.setLong("Last",e.last);n.setLong("Sequence",e.sequence);n.setString("Level",e.level.name());n.setString("Category",e.category.name());n.setString("Target",e.target.name());n.setString("Code",e.code);n.setString("Message",e.message);n.setInteger("Repeats",e.repeats);n.setInteger("Currency",e.currency);n.setLong("Amount",e.amount);return n;}
    static Entry read(NBTTagCompound n){if(!n.hasUniqueId("Key")||!n.hasUniqueId("Owner")||!n.hasUniqueId("Scope"))return null;try{Entry e=new Entry(n.getUniqueId("Key"),n.getUniqueId("Owner"),n.getUniqueId("Scope"),n.hasUniqueId("Source")?n.getUniqueId("Source"):null,n.getLong("First"),n.getLong("Sequence"),Level.valueOf(n.getString("Level")),Category.valueOf(n.getString("Category")),Target.valueOf(n.getString("Target")),n.getString("Code"),n.getString("Message"),n.getInteger("Currency"),n.getLong("Amount"));e.origin=n.hasUniqueId("Origin")?n.getUniqueId("Origin"):e.scope;e.last=Math.max(e.first,n.getLong("Last"));e.repeats=Math.max(1,n.getInteger("Repeats"));return e;}catch(IllegalArgumentException ex){return null;}}
    static NBTTagList write(EventJournal j){NBTTagList list=new NBTTagList();for(Entry e:j.all())list.appendTag(tag(e));return list;}
    static void load(EventJournal j,NBTTagList list){j.clear();Set<UUID> seen=new HashSet<>();for(int i=0;i<list.tagCount();i++){Entry e=read(list.getCompoundTagAt(i));if(e!=null&&seen.add(e.id))j.restore(e);}j.configure(ODC.journalLimit);}
    static List<Entry> recent(Tiles.Owned t,TaskData d,int count){List<Entry> rows=d.journal.recent(t.owner,scopes(t));return new ArrayList<>(rows.subList(0,Math.min(Math.max(0,count),rows.size())));}
    static int errors(Tiles.Owned t,TaskData d){int n=0;for(Entry e:recent(t,d,d.journal.limit()))if(e.level==Level.ERROR||e.level==Level.CRITICAL)n++;return n;}
    static List<Entry> financial(Tiles.Owned t,TaskData d){List<Entry> rows=recent(t,d,d.journal.limit());rows.removeIf(e->e.category!=Category.FINANCE);return rows;}
    static void snapshot(PanelMenu m,TaskData d,NBTTagCompound out){Map<UUID,String> servers=new HashMap<>(),jobs=new HashMap<>();for(Menus.Target t:DataOSView.servers(m.tile))servers.put(ClusterScheduler.serverId(t.item),t.item.getDisplayName());for(TaskData.Job j:DataOSView.jobs(m.tile,d))if(!j.terms.hasKey("End")&&!j.terms.getBoolean("Finished"))jobs.put(j.terms.getUniqueId("Key"),"Task #"+j.id);List<Entry> entries=EventJournal.filter(recent(m.tile,d,d.journal.limit()),m.eventQuery.search,m.eventQuery.category,m.eventQuery.level,m.eventQuery.oldest,e->e.target==Target.SERVER?servers.getOrDefault(e.source,""):e.target==Target.TASK?jobs.getOrDefault(e.source,""):"");out.setString("Query",m.eventQuery.encode());out.setInteger("Count",entries.size());int start=Math.min(Math.max(0,m.scrollRow),Math.max(0,entries.size()-1));out.setInteger("Start",start);NBTTagList rows=new NBTTagList();for(int i=start;i<Math.min(start+DataOSView.WINDOW,entries.size());i++)rows.appendTag(row(entries.get(i),servers,jobs));out.setTag("Rows",rows);if(!TaskConsole.NONE.equals(m.detailEvent))for(Entry e:recent(m.tile,d,d.journal.limit()))if(e.id.equals(m.detailEvent)){out.setTag("EventDetail",row(e,servers,jobs));break;}}
    static NBTTagCompound row(Entry e,Map<UUID,String> servers,Map<UUID,String> jobs){NBTTagCompound n=tag(e);String label=e.source==null?"—":e.source.toString().substring(0,8);Map<UUID,String> labels=e.target==Target.SERVER?servers:e.target==Target.TASK?jobs:Collections.emptyMap();if(labels.containsKey(e.source)){label=labels.get(e.source);n.setBoolean("Link",true);}n.setString("Label",label);return n;}
    // Compare partitions of known, currently visible devices. Do not infer a split solely from disappearance of a member.
    static final class Topology {
        final UUID owner;final Set<UUID> members;final Set<BlockPos> positions;Topology(UUID o,Set<UUID> m,Set<BlockPos> p){owner=o;members=new HashSet<>(m);positions=new HashSet<>(p);}
    }
    static void observe(World w,TaskData d,List<Topology> current){Map<UUID,Topology> prev=d.eventTopology,next=new HashMap<>();for(Topology t:current)for(UUID id:t.members)next.put(id,t);
        for(Topology t:current){Set<Topology> old=new HashSet<>();for(UUID id:t.members){Topology before=prev.get(id);if(before!=null&&before.owner.equals(t.owner))old.add(before);}boolean uncertain=false,split=false;for(Topology before:old){for(BlockPos p:before.positions)if(!w.isBlockLoaded(p)){uncertain=true;break;}Set<Topology> pieces=new HashSet<>();for(UUID id:before.members)if(next.containsKey(id)&&next.get(id).owner.equals(t.owner))pieces.add(next.get(id));if(pieces.size()>1)split=true;}UUID anchor=t.members.stream().min(Comparator.comparing(UUID::toString)).orElse(null);if(anchor==null)continue;if(!uncertain){if(old.size()>1)d.record(t.owner,anchor,null,Level.INFO,Category.NETWORK,Target.NONE,"network_merge","Data networks merged",-1,0);if(split)d.record(t.owner,anchor,null,Level.WARNING,Category.NETWORK,Target.NONE,"network_split","Data network split",-1,0);d.journal.prune(t.owner,t.members);} }
        // Keep last complete topology for partially unloaded domains; discard fully absent loaded groups.
        Map<UUID,Topology> merged=new HashMap<>(next);for(Map.Entry<UUID,Topology> e:prev.entrySet()){boolean partial=false;for(BlockPos p:e.getValue().positions)if(!w.isBlockLoaded(p)){partial=true;break;}if(partial)merged.put(e.getKey(),e.getValue());}d.eventTopology=merged;
    }
}
